package cache

imports: container/list, sync, time

type cacheEntry[K comparable, V any] struct {
  key K
  value V
  expiresAt time.Time
}

type Cache[K comparable, V any] struct {
  mu sync.RWMutex
  maxSize int
  defaultTTL time.Duration
  items map[K]*list.Element  // key -> list element containing *cacheEntry
  evictList *list.List        // front = most recent, back = least recent
}

func New[K,V](maxSize int, defaultTTL time.Duration) *Cache[K,V]:
  return &Cache{items: make(map), evictList: list.New(), maxSize, defaultTTL}

func (c *Cache) Get(key K) (V, bool):
  RLock -> find in map -> if not found: return zero, false
  if expired (time.Now().After(expiresAt)): Unlock, call Delete(key), return zero, false
  MoveToFront(element)
  return entry.value, true

func (c *Cache) Set(key K, value V):
  call SetWithTTL(key, value, c.defaultTTL)

func (c *Cache) SetWithTTL(key K, value V, ttl time.Duration):
  Lock
  if key exists in map: update value, update expiresAt, MoveToFront, return
  if len(items) >= maxSize: evict back element (delete from map + remove from list)
  entry := &cacheEntry{key, value, time.Now().Add(ttl)}
  element := evictList.PushFront(entry)
  items[key] = element

func (c *Cache) Delete(key K):
  Lock
  if element exists in map: evictList.Remove(element), delete from map

func (c *Cache) Len() int:
  RLock; return len(items)

func (c *Cache) Clear():
  Lock; evictList.Init(); items = make(map)
